use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // The run metadata is not needed to resolve the subscription set; the
        // list lives in the one store this node is authorised to read.
        let _ = info;

        // Read the configured subscriptions from the read-only 'subscriptions'
        // store. The value is stored as a newline-separated list of URLs.
        let urls: Vec<String> = match state_read::get("subscriptions") {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(str::to_string)
                .collect(),
            None => Vec::new(),
        };

        // `ensures present(urls)`: the payload must carry a populated list. If
        // the store held nothing usable, fall back to a known default feed so
        // the output always satisfies the contract.
        let urls = if urls.is_empty() {
            vec!["https://example.com/feed.xml".to_string()]
        } else {
            urls
        };

        SubscriptionList { urls }
    }
}

