}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

/// Keys the 'subscriptions' store may hold the list under, tried in order.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds", "list"];

/// Pull every http(s) URL out of a stored value. This accepts a JSON array of
/// strings, or a newline-, comma- or whitespace-separated list.
fn parse_urls(raw: &str) -> Vec<String> {
    let cleaned = raw.replace("\\/", "/");
    let mut out: Vec<String> = Vec::new();
    for token in cleaned.split(|c: char| {
        c.is_whitespace() || matches!(c, ',' | '[' | ']' | '"' | '\'' | ';')
    }) {
        let t = token.trim();
        if (t.starts_with("https://") || t.starts_with("http://"))
            && !out.iter().any(|u| u == t)
        {
            out.push(t.to_string());
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // The run metadata does not affect which feeds are subscribed.
        let _ = info;

        // Read the subscription set from the one store this node may read.
        // Never fabricate URLs: downstream fetches are limited to an allowlist,
        // and the list must reflect configured state only.
        let mut urls: Vec<String> = Vec::new();
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let parsed = parse_urls(&raw);
                if !parsed.is_empty() {
                    urls = parsed;
                    break;
                }
            }
        }

        // `ensures present(urls)`: the field is always populated with a list,
        // even if it is empty because the store held nothing usable.
        SubscriptionList { urls }
    }
}

export!(Node);
